double *transform_gcps(double source_x[], double source_y[], double target_x[], double target_y[], int num_gcps, int polynomial_order) {
    // Define the polynomial model coefficients
    double coefficients[polynomial_order + 1][polynomial_order + 1];

    // Perform the transformation
    double *transformed_x = (double *)malloc(num_gcps * sizeof(double));
    double *transformed_y = (double *)malloc(num_gcps * sizeof(double));

    for (int i = 0; i < num_gcps; i++) {
        transformed_x[i] = 0;
        transformed_y[i] = 0;
        for (int j = 0; j <= polynomial_order; j++) {
            for (int k = 0; k <= polynomial_order; k++) {
                transformed_x[i] += coefficients[j][k] * pow(source_x[i], j) * pow(source_y[i], k);
                transformed_y[i] += coefficients[j][k] * pow(source_x[i], j) * pow(source_y[i], k);
            }
        }
    }

    return transformed_x;
}
