void parse_command(const char* command, char** name, char*** arguments, int* num_arguments) {
    *name = NULL;
    *arguments = NULL;
    *num_arguments = 0;

    char* temp = strdup(command);
    *name = strtok(temp, " ");
    if (*name == NULL) {
        printf("Error: Empty command.\n");
        return;
    }
    *num_arguments = 0;
    while (strtok(NULL, " ") != NULL) (*num_arguments)++;
    if (*num_arguments == 0) {
        printf("No arguments found.\n");
        return;
    }
    *arguments = (char**)malloc(*num_arguments * sizeof(char*));
    char* token = strtok(temp, " ");
    for (int i = 0; i < *num_arguments; i++) {
        token = strtok(NULL, " ");
        (*arguments)[i] = strdup(token);
    }
    free(temp);
}
