void** create_folds_list(int* data, int len, int count) {
    // Return NULL if count is non-positive
    if (count <= 0) {
        return NULL;
    }

    // Calculate fold size and remainder
    int fold_size = len / count;
    int remainder = len % count;

    // Allocate memory for the folds
    void** folds = malloc(count * sizeof(void*));
    if (!folds) {
        return NULL; // Return NULL if memory allocation fails
    }

    int start_index = 0;
    for (int i = 0; i < count; i++) {
        // Allocate memory for each fold (with possible extra element)
        int current_fold_size = fold_size + (i < remainder ? 1 : 0);
        int* fold = malloc(current_fold_size * sizeof(int));
        if (!fold) {
            // Free any previously allocated memory if allocation fails
            for (int j = 0; j < i; j++) {
                free(folds[j]);
            }
            free(folds);
            return NULL;
        }

        // Copy data into the fold
        for (int j = 0; j < current_fold_size; j++) {
            fold[j] = data[start_index + j];
        }

        folds[i] = fold; // Store the fold pointer
        start_index += current_fold_size;
    }

    return folds;
}
