float calculate_top_k_accuracy(float** predictions, int* targets, int batch_size, int num_classes, int k) {
    int correct = 0;
    for (int i = 0; i < batch_size; ++i) {
        int* top_indices = (int*)malloc(sizeof(int) * num_classes);
        for (int j = 0; j < num_classes; ++j) top_indices[j] = j;

        // Sort indices by descending scores
        for (int m = 0; m < num_classes - 1; ++m) {
            for (int n = m + 1; n < num_classes; ++n) {
                if (predictions[i][top_indices[n]] > predictions[i][top_indices[m]]) {
                    int temp = top_indices[m];
                    top_indices[m] = top_indices[n];
                    top_indices[n] = temp;
                }
            }
        }

        // Check if target is in top-k
        for (int j = 0; j < k; ++j) {
            if (top_indices[j] == targets[i]) {
                correct++;
                break;
            }
        }

        free(top_indices);
    }
    return (float)correct / batch_size;
}
