int parse_duration(const char *duration_str) {
    int value;
    char unit[10];

    // Try to extract the number and the unit from the string
    if (sscanf(duration_str, "%d%9s", &value, unit) != 2) {
        // If the input format is invalid, return -1 (error)
        return -1;
    }

    // Convert unit to lowercase
    for (int i = 0; unit[i]; i++) {
        unit[i] = tolower((unsigned char)unit[i]);
    }

    // Determine the number of seconds based on the unit
    if (strcmp(unit, "s") == 0 || strcmp(unit, "sec") == 0) {
        return value;
    } else if (strcmp(unit, "m") == 0 || strcmp(unit, "min") == 0) {
        return value * 60;
    } else if (strcmp(unit, "h") == 0 || strcmp(unit, "hour") == 0) {
        return value * 3600;
    } else if (strcmp(unit, "d") == 0 || strcmp(unit, "day") == 0) {
