<response>
Here's a concise function `string_to_list` to transform a comma-separated string into a list, replacing " and " with a comma, splitting the result, and stripping whitespace:

```c
char** string_to_list(const char* input, int* count) {
    // Create a copy of the input string to manipulate safely
    char* phrase_copy = strdup(input);

    // Replace " and " with commas
    char* and_pos = strstr(phrase_copy, " and ");
    while (and_pos != NULL) {
        *and_pos = ',';  // Replace " and " with a comma
        memmove(and_pos + 1, and_pos + 4, strlen(and_pos + 4) + 1); // Shift the rest of the string
        and_pos = strstr(phrase_copy, " and "); // Find the next " and "
    }

    // Tokenize the string by commas
    char* token = strtok(phrase_copy, ",");
    int size = 0;
    // Calculate number of tokens (words)
    while (token != NULL) {
        size++;
        token = strtok(NULL, ",");
    }

    // Allocate memory for the array of strings
    char** result = (char**)malloc(size * sizeof(char*));

    // Rewind tokenization
    token = strtok(phrase_copy, ",");
    int index = 0;

    // Tokenize and trim spaces, store in result array
    while (token != NULL) {
        while (*token == ' ') token++;  // Trim leading spaces
        char* end = token + strlen(token) - 1;
        while (end > token && *end == ' ') end--;  // Trim trailing spaces
        *(end + 1) = '\0';  // Null-terminate the trimmed token

        result[index] = strdup(token);  // Copy the token into the result array
        index++;
        token = strtok(NULL, ",");
    }

    *count = size;  // Return the number of tokens
    free(phrase_copy);
    return result;
}
```

This approach ensures no empty strings are included if there are excess commas or spaces.
