	LL_TIM_SetEncoderMode(TIMx, TIM_EncoderInitStruct->EncoderMode);

	/* Write to TIMx CCMR1 */
	LL_TIM_WriteReg(TIMx, CCMR1, tmpccmr1);

	/* Write to TIMx CCER */
