```c
const char* format_size(long long size_bytes) {
    static char result[20];
    const char* units[] = {"bytes", "KB", "MB", "GB", "TB"};
    double num = (double)size_bytes;

    // Special case for 0 bytes
    if (size_bytes == 0) {
        snprintf(result, sizeof(result), "0.0bytes");
        return result;
    }

    // Iterate through units
    for (int i = 0; i < 5; i++) {
        if (num < 1024.0) {
            snprintf(result, sizeof(result), "%.1f%s", num, units[i]);
            return result;
        }
        num /= 1024.0;
    }

    // Return for 'TB' unit if the number is large enough
    snprintf(result, sizeof(result), "%.1f%s", num, units[4]);
    return result;
}

