```c
int count_conditional_matches(const char* str1, const char* str2, bool strict) {
    int count = 0;
    int i = strlen(str1) - 1; // Pointer for the end of str1
    int j = 0; // Pointer for the beginning of str2

    while (i >= 0 && j < strlen(str2)) {
        if (str1[i] == str2[j]) {
            count++;
            i--; // Move backward on str1
            j++; // Move forward on str2
        } else {
            if (strict) {
                // Stop counting as soon as a mismatch is found
                break;
            } else {
                // Skip the non-matching character in str1 and continue matching with next character in str2
                i--;
            }
        }
    }

    return count;
}
