A C function to calculate the ratio of two integers and return the result as a string can be implemented as follows:

```c
char* ratio(int numerator, int denominator) {
    if (denominator == 0) {
        throw ValueError("Division by zero is undefined.");
    }

    if (numerator == 0) {
        return "0";
    }

    int gcd = 1;
    for (int i = 2; i <= numerator && i <= denominator; i++) {
        if (numerator % i == 0 && denominator % i == 0) {
            gcd = i;
        }
    }

    numerator /= gcd;
    denominator /= gcd;

    char* result = malloc(32);
    sprintf(result, "%d/%d", numerator, denominator);

    return result;
}
```

