Pair* find_pairs(int* numbers, int size, float growth_ratio, int maximum_distance, int* result_size) {
    // Allocate an array to store the pairs, initially assume max possible pairs
    int max_pairs = size * (size - 1) / 2;  // Maximum number of pairs possible
    Pair* pairs = (Pair*)malloc(max_pairs * sizeof(Pair));
    *result_size = 0;  // Initialize the result size to 0

