    char buffer[8]; 
    int i = 0;

    if (value == 0) {
        char* result = (char*)malloc(2);  
        result[0] = 63; // ASCII '?'
        result[1] = '\0';
        return result;
    }

    while (value > 0) {
        unsigned char chunk = value & 0x1F; 
        value >>= 5;
        if (value > 0) {
